insert into fina_treatment_info (treatment_name, create_time, create_by, 
  delete_flag, update_time, update_by
  )
values (#{treatmentName,jdbcType=VARCHAR}, #{createTime,jdbcType=TIMESTAMP}, #{createBy,jdbcType=VARCHAR}, 
  #{deleteFlag,jdbcType=INTEGER}, #{updateTime,jdbcType=TIMESTAMP}, #{updateBy,jdbcType=VARCHAR}
  )

mapper.select:
select a.* from fina_treatment_info a left join fina_diagnosis_treatment_mid b on a.id = b.treatment_id where a.delete_flag =0 and b.delete_flag =0
and b.diagnosis_id = #{diagnosisId,jdbcType=INTEGER}
order by a.id desc
